-- Step 2: every piece keeps its current category.
INSERT INTO "product_category" ("product_id", "category_id") SELECT "id", "category_id" FROM "product" WHERE "category_id" IS NOT NULL ON CONFLICT DO NOTHING;--> statement-breakpoint
-- Step 3: the category "featured" (Hebrew "מומלצות") goes last; an existing one is reused.
INSERT INTO "category" ("slug", "name_he", "name_en", "sort_order") SELECT 'featured', 'מומלצות', 'Featured', coalesce(max("sort_order"), -1) + 1 FROM "category" ON CONFLICT ("slug") DO NOTHING;--> statement-breakpoint
-- Step 4: every existing piece (any state) is added to it; only published ones are shown.
INSERT INTO "product_category" ("product_id", "category_id") SELECT p."id", c."id" FROM "product" p CROSS JOIN "category" c WHERE c."slug" = 'featured' ON CONFLICT DO NOTHING;--> statement-breakpoint
-- Step 5: the home row shows it. A database without a settings row gets it from the seed.
